options.getOption:
const data = context.panel.data;
if (!data || !data.series || data.series.length === 0) return {};

const series = data.series[0];
const fields = {};
series.fields.forEach(f => { fields[f.name] = f; });

const msgCount = fields.type ? fields.type.values.length : 0;
if (msgCount === 0) return {};

let html = '<div style="font-family: -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif; max-width: 900px; margin: 0 auto; padding: 16px; overflow-y: auto; max-height: 100%;">';

for (let i = 0; i < msgCount; i++) {
  const type = fields.type.values[i];
  const role = fields.role.values[i];
  const text = fields.content_text ? (fields.content_text.values[i] || '') : '';
  const timeStr = fields.time_str ? fields.time_str.values[i] : '';
  const model = fields.model ? (fields.model.values[i] || '') : '';
  const contentJson = fields.content_json ? fields.content_json.values[i] : null;

  if (type === 'user') {
    const displayText = text.length > 500 ? text.substring(0, 500) + '...' : text;
    const escapedText = displayText.replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
    html += '<div style="display: flex; justify-content: flex-end; margin-bottom: 12px;">';
    html += '<div style="background: #e67e22; color: white; padding: 10px 14px; border-radius: 12px 12px 2px 12px; max-width: 75%; font-size: 13px;">';
    html += '<div style="font-size: 10px; opacity: 0.8; margin-bottom: 4px;">USER ' + timeStr + '</div>';
    html += escapedText;
    html += '</div></div>';
  } else if (type === 'assistant') {
    // Parse content_json to find tool_use blocks
    let blocks = [];
    if (contentJson) {
      try {
        const parsed = JSON.parse(contentJson);
        if (Array.isArray(parsed)) {
          blocks = parsed;
        }
      } catch(e) {}
    }

    // If we have structured content blocks, render them
    if (blocks.length > 0) {
      html += '<div style="margin-bottom: 12px;">';
      html += '<div style="font-size: 10px; color: #888; margin-bottom: 4px;">ASSISTANT ' + timeStr + (model ? ' (' + model.replace('claude-', '') + ')' : '') + '</div>';

      for (const block of blocks) {
        if (block.type === 'text' && block.text) {
          const t = block.text.length > 1000 ? block.text.substring(0, 1000) + '...' : block.text;
          const escaped = t.replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
          html += '<div style="background: #2d2d2d; color: #e0e0e0; padding: 10px 14px; border-radius: 12px 12px 12px 2px; max-width: 85%; font-size: 13px; margin-bottom: 6px;">';
          html += escaped;
          html += '</div>';
        } else if (block.type === 'tool_use') {
          const toolName = block.name || 'unknown';
          let inputPreview = '';
          if (block.input) {
            if (block.input.command) inputPreview = block.input.command.substring(0, 80);
            else if (block.input.file_path) inputPreview = block.input.file_path;
            else if (block.input.pattern) inputPreview = block.input.pattern;
            else if (block.input.query) inputPreview = block.input.query.substring(0, 80);
            else if (block.input.prompt) inputPreview = block.input.prompt.substring(0, 80);
            else inputPreview = JSON.stringify(block.input).substring(0, 80);
          }
          const escapedPreview = inputPreview.replace(/</g, '&lt;').replace(/>/g, '&gt;');
          let toolColor = '#6c5ce7';
          if (['Read','Glob','Grep'].includes(toolName)) toolColor = '#0984e3';
          else if (['Write','Edit','NotebookEdit'].includes(toolName)) toolColor = '#00b894';
          else if (toolName === 'Bash') toolColor = '#d63031';
          else if (toolName === 'Agent') toolColor = '#00cec9';
          html += '<div style="background: ' + toolColor + '22; border-left: 3px solid ' + toolColor + '; padding: 6px 10px; border-radius: 4px; max-width: 85%; font-size: 12px; margin-bottom: 4px; color: #ccc;">';
          html += '<span style="color: ' + toolColor + '; font-weight: bold;">' + toolName + '</span>';
          if (escapedPreview) html += ' <span style="opacity: 0.7;">' + escapedPreview + '</span>';
          html += '</div>';
        } else if (block.type === 'tool_result') {
          let resultText = '';
          if (typeof block.content === 'string') resultText = block.content;
          else if (Array.isArray(block.content)) {
            resultText = block.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
          }
          if (resultText) {
            const truncated = resultText.length > 200 ? resultText.substring(0, 200) + '...' : resultText;
            const escaped = truncated.replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
            html += '<div style="background: #1a1a2e; border-left: 3px solid #555; padding: 6px 10px; border-radius: 4px; max-width: 85%; font-size: 11px; margin-bottom: 6px; color: #999; font-family: monospace;">';
            html += escaped;
            html += '</div>';
          }
        }
      }
      html += '</div>';
    } else if (text) {
      // Fallback: plain text rendering
      const displayText = text.length > 1000 ? text.substring(0, 1000) + '...' : text;
      const escapedText = displayText.replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
      html += '<div style="margin-bottom: 12px;">';
      html += '<div style="font-size: 10px; color: #888; margin-bottom: 4px;">ASSISTANT ' + timeStr + '</div>';
      html += '<div style="background: #2d2d2d; color: #e0e0e0; padding: 10px 14px; border-radius: 12px 12px 12px 2px; max-width: 85%; font-size: 13px;">';
      html += escapedText;
      html += '</div></div>';
    }
  }
}

html += '</div>';

const container = context.panel.chart.getDom();
container.innerHTML = html;
container.style.overflow = 'auto';

return {};
